<script setup>import {ref} from 'vue';import {state,actions} from '../../domain/prototypeStore.js';import StatusTag from '../../components/StatusTag.vue';const actual=ref(state.inventory.actualQuantity??'');const message=ref('');const submit=()=>{const r=actions.submitInventory(actual.value);message.value=r.message||(r.ok?'盘点结果已提交，等待 Web 复核':'操作失败')}</script>
<template><section class="h5-page"><div class="h5-module-hero"><span>盘</span><h2>移动物资盘点</h2><p>G2-FR-008—009、025</p></div><div v-if="message" class="action-message">{{message}}</div><div class="h5-card"><header><strong>{{state.inventory.item}}</strong><StatusTag :text="state.inventory.status"/></header><p>站点：{{state.inventory.station}}</p><p>计划快照：{{state.inventory.bookQuantity}}</p><label>现场数量<input v-model="actual" type="number" min="0" step="1"></label><p v-if="state.inventory.difference!==null">差异：<strong :class="{danger:state.inventory.difference}">{{state.inventory.difference}}</strong></p><button class="primary-button active" @click="submit">提交盘点</button></div></section></template>